#!/usr/bin/env python3
"""AMLGuard — Day 1 scaffold bootstrap (end-to-end MLOps schedule).

Run from the repository root:

    python apply_day1.py

Creates the professional package structure, writes the central config, the
day-stamped stubs, the frozen baseline and docs, and removes the two old flat
modules (src/features.py, src/api.py) in the correct order so that the
src/features/ package can be created without collision. Idempotent.
"""
import base64, os, sys

if not os.path.isdir(".git") or not os.path.isdir("notebooks"):
    sys.exit("Run this from the amlguard repository root (where .git/ lives).")

DELETE = ['src/features.py', 'src/api.py']
FILES = {
    '.github/workflows/.gitkeep': '',
    '.gitignore': '',
    'artifacts/.gitkeep': '',
    'artifacts/baseline_metrics.json': '',
    'cloud/.gitkeep': '',
    'docs/BASELINE.md': '',
    'pyproject.toml': '',
    'requirements-dev.txt': 'IyBEZXZlbG9wbWVudCAvIENJIGRlcGVuZGVuY2llcyAoc2VlIHB5cHJvamVjdC50b21sIFtwcm9qZWN0Lm9wdGlvbmFsLWRlcGVuZGVuY2llc10uZGV2KQotciByZXF1aXJlbWVudHMudHh0CnB5dGVzdD49OC4wCnJ1ZmY+PTAuNApodHRweD49MC4yNyAgICAgICAgICAjIEZhc3RBUEkgVGVzdENsaWVudCB0cmFuc3BvcnQK',
    'src/__init__.py': 'IiIiQU1MR3VhcmQg4oCUIGFudGktbW9uZXktbGF1bmRlcmluZyBkZXRlY3Rpb24gcGlwZWxpbmUuIiIiCgpfX3ZlcnNpb25fXyA9ICIwLjEuMCIK',
    'src/api.py': '',
    'src/api/__init__.py': 'IiIiRmFzdEFQSSBzZXJ2aW5nIGxheWVyLiIiIgo=',
    'src/api/main.py': '',
    'src/config.py': '',
    'src/data/__init__.py': 'IiIiRGF0YSBsb2FkaW5nIGFuZCBzY2hlbWEgdmFsaWRhdGlvbi4iIiIK',
    'src/data/load_data.py': '',
    'src/features.py': '',
    'src/features/__init__.py': '',
    'src/features/build_features.py': '',
    'src/models/__init__.py': 'IiIiVHJhaW5pbmcsIGV2YWx1YXRpb24sIHBlcnNpc3RlbmNlIGFuZCBwcmVkaWN0aW9uLiIiIgo=',
    'src/models/evaluate.py': '',
    'src/models/predict.py': '',
    'src/models/train.py': '',
    'tests/__init__.py': '',
}

for rel in DELETE:
    if os.path.exists(rel):
        os.remove(rel); print("removed", rel)

for rel, b64 in FILES.items():
    os.makedirs(os.path.dirname(rel) or ".", exist_ok=True)
    with open(rel, "wb") as f:
        f.write(base64.b64decode(b64))
    print("wrote  ", rel)

print("\nDone. Review with:  git status")
print("Then:")
print('  git add -A')
print('  git commit -m "refactor: Day 1 — freeze baseline, scaffold src/ tests/ artifacts/ cloud/ .github/"')
print("  git push origin main")
